using System;

class X: Attribute {}
class XAttribute: Attribute {}

class A { [return:X] void M() { } }  // Ambiguous
class B { [@return:X] void M() { } }  // Ambiguous
class C { [return:@X] void M() { } }  // Fine, binds to X
class D { [@return:@X] void M() { } }  // Fine, binds to X

